import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class Main {
    public static void main(String[] args) {
        Map<String, String> initial = new HashMap<String, String>();
        initial.put("G1", "Room1");
        initial.put("G2", "Room2");
        final DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initial);

        Thread t1 = new Thread(() -> tracker.updatePosition("G1", "Room3"));
        Thread t2 = new Thread(() -> tracker.getAllPositionsStatic());
        t1.start();
        t2.start();
        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        System.out.println("G1 position: " + tracker.fetchPosition("G1"));
        System.out.println("Snapshot: " + tracker.getAllPositionsStatic());
    }
}

class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, String> positions;

    public DelegatingDeviceTracker(Map<String, String> initial) {
        this.positions = new ConcurrentHashMap<String, String>();
        for (Map.Entry<String, String> entry : initial.entrySet()) {
            if (entry.getKey() != null && entry.getValue() != null) {
                positions.put(entry.getKey(), entry.getValue());
            }
        }
    }

    public String fetchPosition(String gadgetId) {
        if (gadgetId == null) {
            return null;
        }
        return positions.get(gadgetId);
    }

    public boolean updatePosition(String gadgetId, String position) {
        if (gadgetId == null || position == null) {
            return false;
        }
        return positions.replace(gadgetId, position) != null;
    }

    public Map<String, String> getAllPositionsLive() {
        return Collections.unmodifiableMap(positions);
    }

    public Map<String, String> getAllPositionsStatic() {
        return Collections.unmodifiableMap(new HashMap<String, String>(positions));
    }
}

